/**
 * Theme preview (#949): the rules shared by the React (AweThemePreview) and the AngularJS (aweThemePreview) engines.
 *
 * A palette select and its colour picker give a colour: the palette, or the hex of the picker when the palette is
 * custom. A named palette is drawn at once; a hex is drawn once its palette, generated by the server, has arrived. The
 * preview lives in an iframe of its own, whose root gets the appearance of the theme with applyThemeAppearance and whose
 * head gets the stylesheets of the application.
 */

/** Query that generates the palette of the custom colours (ThemeService.previewPalette) */
export const PREVIEW_PALETTE_QUERY = "ThmPrvPal";
/** Pause after the last change of a custom colour before its palette is requested */
export const PREVIEW_PALETTE_DELAY = 300;
/** Mode of the theme that follows the device: the preview offers a switch to the light or the dark mode */
export const PREVIEW_SYSTEM_MODE = "system";
/** Modes the preview can be drawn in, besides following the device */
export const PREVIEW_MODES = ["light", "dark"];
// Defaults of a theme (ThemeOptions), shown until the criteria have a valid colour
export const PREVIEW_DEFAULT_PRIMARY = "emerald";
export const PREVIEW_DEFAULT_SURFACE = "auto";
/** Palette of the named colours: they need no generated properties */
export const NO_PALETTE = {};

const HEX = /^#([0-9a-f]{3}|[0-9a-f]{6})$/i;
const PALETTE_PROPERTY = /^--awe-(primary|surface)-[a-z0-9-]+$/;
const CUSTOM = "custom";

/**
 * Check whether a colour is a hex
 * @param {string} value Colour
 * @return {boolean} The colour is a valid hex
 */
export const isHex = (value) => HEX.test(value);

/**
 * Colour of a palette select and its colour picker: the palette, or the hex of the picker when the palette is custom
 * @param {string} palette Palette of the select
 * @param {string} hex Hex of the picker
 * @return {string|null} Colour, null when it is not valid (an empty palette, or custom without a valid hex)
 */
export function previewColour(palette, hex) {
  if (palette === CUSTOM) {
    return isHex(hex) ? hex.toUpperCase() : null;
  }
  return palette || null;
}

/**
 * Hexes whose palette the server generates: the colours that are a hex, null the named ones
 * @param {string} primary Primary colour
 * @param {string} surface Surface colour
 * @return {{primaryHex: string|null, surfaceHex: string|null}} Parameters of the palette query
 */
export const previewHexes = (primary, surface) => ({
  primaryHex: isHex(primary) ? primary : null,
  surfaceHex: isHex(surface) ? surface : null
});

/**
 * Generated properties of the answer of the palette query: the columns of its only row
 * @param {object[]} response Client actions of the data action
 * @return {object|null} Properties, null when the answer has no row
 */
export function previewPaletteOf(response) {
  const fill = Array.isArray(response) ? response.find((action) => action.type === "fill") : null;
  const row = fill?.parameters?.datalist?.rows?.[0];
  if (!row) {
    return null;
  }
  return Object.fromEntries(Object.entries(row).filter(([name]) => PALETTE_PROPERTY.test(name)));
}

/**
 * Check whether the preview follows the device: the theme has no light or dark mode
 * @param {string} themeMode Mode of the theme
 * @return {boolean} The preview follows the device
 */
export const followsDevice = (themeMode) => !PREVIEW_MODES.includes(themeMode);

/**
 * Settings of the appearance of the preview (see applyThemeAppearance)
 * @param {{primary: string, surface: string, palette: object}} colours Colours drawn and the palette of their hexes
 * @param {string} mode Mode of the preview
 * @param {string} density Density of the application
 * @return {object} Settings
 */
export const previewAppearance = ({primary, surface, palette}, mode, density) => ({
  themePrimary: primary, themeSurface: surface, themeMode: mode, density, themePalette: palette
});

/**
 * Stylesheets of the application, cloned for the document of the preview
 * @param {Document} target Document of the preview
 * @return {Node[]} Cloned link and style elements
 */
export const cloneStyles = (target) => Array.from(document.head.querySelectorAll("link[rel='stylesheet'], style"))
  .map((node) => target.importNode(node, true));

/**
 * Prepare the document of the preview: the stylesheets and the language of the application, and the class of the page
 * @param {Document} target Document of the preview
 */
export function preparePreviewDocument(target) {
  target.head.replaceChildren(...cloneStyles(target));
  target.documentElement.lang = document.documentElement.lang;
  target.body.className = "awe-theme-preview-page";
}
